from qa import *
st = st_load(); ss = st["sess"]; a = S(); a.login(*PW["admin"])
def slip(t, y, m):
    c, j = a.get(f"/payroll/payslips/?year={y}&month={m}&teacher={ID[t]}"); r = j["results"]; return r[0] if r else None
log("==== TC-018 net-0 re-run", datetime.datetime.now().isoformat())
a.post("/payroll/payslips/generate/", {"year": 2026, "month": 6}); p6 = slip("T6", 2026, 6); log("T6 June", short(p6, ["gross_minor","bonuses_minor","net_minor"]))
c, j = a.post("/payroll/adjustments/", {"teacher": ID["T6"], "kind": "deduction", "amount_minor": p6["net_minor"], "effective_on": "2026-06-20", "reason": "net0"})
a.post("/payroll/payslips/generate/", {"year": 2026, "month": 6}); p6 = slip("T6", 2026, 6); c, j = a.post(f"/payroll/payslips/{p6['id']}/issue/"); log("issue", c, j.get("net_minor"))
c, j = a.post(f"/payroll/payslips/{p6['id']}/mark-paid/", {"paid_on": TODAY.isoformat()}); chk("net-0 paid -> no expense", c == 200 and j["net_minor"] == 0 and q(f"select count(*) from finance_expense where source='payroll.payslip' and source_id={p6['id']}") == "0", f"{c} net={j.get('net_minor')}")
save("tc018.txt")

log("==== TC-019", datetime.datetime.now().isoformat())
t1 = S(); t1.login(*PW["T1"]); T = ID["T1"]
def bal(s=a, qs=f"?teacher={T}"): return s.get("/payroll/balances/" + qs)
c, j = bal(); chk("admin balance 20000/20000", c == 200 and j == [{"currency": "EGP", "balance_minor": 20000, "available_minor": 20000}] or (isinstance(j, dict) and j.get("results") == [{"currency": "EGP", "balance_minor": 20000, "available_minor": 20000}]), f"{c} {short(j)}")
c, j = bal(t1, ""); chk("teacher own balance same", c == 200 and "20000" in json.dumps(j), f"{c} {short(j)}")
c, W1 = t1.post("/payroll/withdrawals/", {"amount_minor": 8000, "currency": "EGP", "notes": "rent"}); chk("W1 8000 201 under_review", c == 201 and W1["status"] == "under_review", f"{c} {short(W1, n=300)}")
c, j = bal(); chk("available 12000", "12000" in json.dumps(j) and '"balance_minor": 20000' in json.dumps(j), short(j))
c, j = t1.post("/payroll/withdrawals/", {"amount_minor": 13000, "currency": "EGP"}); chk("13000 409 insufficient", c == 409 and j.get("code") == "payroll.insufficient_balance", f"{c} {short(j)}")
c, W2 = t1.post("/payroll/withdrawals/", {"amount_minor": 12000, "currency": "EGP"}); chk("W2 12000 201", c == 201, str(c))
c, j = t1.post("/payroll/withdrawals/", {"amount_minor": 1, "currency": "EGP"}); chk("1 more 409", c == 409, str(c))
c, j = a.post(f"/payroll/withdrawals/{W1['id']}/approve/"); chk("approve W1", c == 200 and j["status"] == "approved", f"{c} {short(j, n=200)}")
c, j = a.post(f"/payroll/withdrawals/{W1['id']}/pay/", {"paid_on": d(1)}); chk("pay tomorrow 400", c == 400, f"{c} {short(j)}")
c, j = a.post(f"/payroll/withdrawals/{W1['id']}/pay/", {"paid_on": d(-1)}); chk("pay before request day 400", c == 400, f"{c} {short(j)}")
c, j = a.post(f"/payroll/withdrawals/{W1['id']}/pay/", {"paid_on": TODAY.isoformat()}); chk("pay W1 paid", c == 200 and j["status"] == "paid", f"{c} {short(j, n=200)}")
c, j = bal(); chk("balance 12000 available 0", '"balance_minor": 12000' in json.dumps(j) and '"available_minor": 0' in json.dumps(j), short(j))
c, j = a.post(f"/payroll/withdrawals/{W2['id']}/reject/", {"office_notes": ""}); chk("reject blank 400 office_notes", c == 400 and "office_notes" in j, f"{c} {short(j)}")
c, j = a.post(f"/payroll/withdrawals/{W2['id']}/reject/", {"office_notes": "Not this month"}); chk("reject with reason", c == 200 and j["status"] == "rejected", f"{c}")
c, j = t1.get(f"/payroll/withdrawals/{W2['id']}/"); chk("T1 sees reason", c == 200 and "Not this month" in json.dumps(j, ensure_ascii=False), f"{c} {short(j, n=300)}")
c, j = bal(); chk("available back 12000", '"available_minor": 12000' in json.dumps(j), short(j))
c, W3 = t1.post("/payroll/withdrawals/", {"amount_minor": 1000, "currency": "EGP"}); c, j = t1.post(f"/payroll/withdrawals/{W3['id']}/cancel/"); chk("T1 cancels under_review", c == 200 and j["status"] == "cancelled", f"{c} {short(j, n=150)}")
c, W4 = t1.post("/payroll/withdrawals/", {"amount_minor": 1000, "currency": "EGP"}); a.post(f"/payroll/withdrawals/{W4['id']}/approve/")
c, j = t1.post(f"/payroll/withdrawals/{W4['id']}/cancel/"); chk("T1 cancel approved 409", c == 409, f"{c} {short(j)}")
c, j = a.post(f"/payroll/withdrawals/{W4['id']}/cancel/"); chk("admin cancels approved", c == 200 and j["status"] == "cancelled", f"{c}")
for b, lab in [({"amount_minor": 0, "currency": "EGP"}, "0"), ({"amount_minor": -1, "currency": "EGP"}, "-1"), ({"amount_minor": 10, "currency": "USD"}, "USD"), ({"amount_minor": 10, "currency": "egp"}, "egp")]:
    c, j = t1.post("/payroll/withdrawals/", b); log(f"invalid {lab}", c, short(j)); chk(f"invalid {lab} rejected 400", c == 400, str(c))
c, j = a.post("/payroll/withdrawals/", {"teacher": T, "amount_minor": 500, "currency": "EGP"}); chk("admin creates for T1", c == 201 and j["teacher"]["id"] == T, f"{c} {short(j, n=200)}"); st["W5"] = j.get("id")
c, j = t1.post("/payroll/withdrawals/", {"teacher": ID["T2"], "amount_minor": 500, "currency": "EGP"}); chk("teacher passing other teacher id ignored (own)", c == 201 and j["teacher"]["id"] == T, f"{c} {short(j, n=200)}"); st["W6"] = j.get("id")
log("DB withdrawals", q("select id,teacher_id,amount_minor,currency,status,decided_by_id,paid_by_id,paid_on from payroll_withdrawalrequest order by id"))
log("DB balancelock", q("select * from payroll_balancelock"))
derived = q("select (select coalesce(sum(net_minor),0) from payroll_payslip where teacher_id=1 and paid_to_balance and status='paid') - (select coalesce(sum(amount_minor),0) from payroll_withdrawalrequest where teacher_id=1 and status='paid')")
c, j = bal(); chk("derived balance = API", f'"balance_minor": {derived}' in json.dumps(j), f"derived {derived} api {short(j)}")
chk("no expense for withdrawal pay", q("select count(*) from finance_expense where source<>'payroll.payslip'") == q("select count(*) from finance_expense where source<>'payroll.payslip'") and q("select count(*) from finance_expense where source like '%withdraw%'") == "0")
for k in ["W5", "W6"]: a.post(f"/payroll/withdrawals/{st[k]}/cancel/")
st_save(st); save("tc019.txt")

log("==== TC-020", datetime.datetime.now().isoformat())
c, j = bal(); log("before", short(j))  # available 12000
res = par([lambda: t1.post("/payroll/withdrawals/", {"amount_minor": 12000, "currency": "EGP"}) for _ in range(5)])
codes = sorted(r[0] for r in res); chk("5 parallel 12000: exactly one 201, rest 409", codes == [201, 409, 409, 409, 409], str(codes) + " " + str([r[1].get("code") for r in res if r[0] != 201]))
win = [r[1]["id"] for r in res if r[0] == 201]
s = q("select coalesce(sum(amount_minor),0) from payroll_withdrawalrequest where teacher_id=1 and status in ('under_review','approved','paid')"); chk("sum reserved+paid <= 20000", int(s) <= 20000, s)
if win:
    w = win[0]; a2 = S(); a2.login(*PW["admin"])
    res = par([lambda: a.post(f"/payroll/withdrawals/{w}/approve/"), lambda: a2.post(f"/payroll/withdrawals/{w}/reject/", {"office_notes": "race"})])
    log("approve vs reject", [(r[0], r[1].get("status") or r[1].get("code")) for r in res]); chk("one winner one 409", sorted(r[0] for r in res) == [200, 409])
    log("final", q(f"select status from payroll_withdrawalrequest where id={w}"))
    a.post(f"/payroll/withdrawals/{w}/cancel/")
c, W7 = t1.post("/payroll/withdrawals/", {"amount_minor": 100, "currency": "EGP"}); a.post(f"/payroll/withdrawals/{W7['id']}/approve/")
res = par([lambda: a.post(f"/payroll/withdrawals/{W7['id']}/pay/", {"paid_on": TODAY.isoformat()}), lambda: a2.post(f"/payroll/withdrawals/{W7['id']}/cancel/")])
log("pay vs cancel", [(r[0], r[1].get("status") or r[1].get("code")) for r in res]); chk("pay vs cancel one winner", sorted(r[0] for r in res) == [200, 409])
c, j = bal(); chk("available never negative", all(x["available_minor"] >= 0 for x in (j if isinstance(j, list) else j.get("results", []))), short(j))
save("tc020.txt")

log("==== TC-021", datetime.datetime.now().isoformat())
t2 = S(); t2.login(*PW["T2"])
dr = slip("T1", 2026, 10); c, j = t1.post(f"/payroll/payslips/{dr['id']}/acknowledge/"); chk("ack draft 404", c == 404, str(c))
# issued T1 payslip: none currently issued-unpaid for T1 -> use T2? T2 Sept draft. Issue T7 Oct? not over. Use T3 Aug issued (TC-014) -> T3 ack
t3 = S(); t3.login(*PW["T3"]); p3 = slip("T3", 2026, 8); c, j = t3.post(f"/payroll/payslips/{p3['id']}/acknowledge/"); chk("ack issued 409 not_allowed_in_status", c == 409 and j.get("code") == "payroll.not_allowed_in_status", f"{c} {short(j)}")
pa = st["slip_T1_aug"]; c, j = t2.post(f"/payroll/payslips/{pa}/acknowledge/"); chk("T2 acks T1's 404", c == 404, str(c))
c, j = t1.post(f"/payroll/payslips/{pa}/acknowledge/"); chk("own paid ack 200", c == 200 and j["acknowledged_at"], str(c))
c, j = t1.post(f"/payroll/payslips/{pa}/acknowledge/"); chk("again 409 already_acknowledged", c == 409 and j.get("code") == "payroll.already_acknowledged", f"{c} {short(j)}")
for who in ["admin", "s_pay", "student", "parent"]:
    s_ = S(); s_.login(*PW[who]); c, j = s_.post(f"/payroll/payslips/{st['slip_T1_sep']}/acknowledge/"); chk(f"{who} ack 403", c == 403, str(c))
c, j = anon().post(f"/payroll/payslips/{st['slip_T1_sep']}/acknowledge/"); chk("anon 401/403", c in (401, 403), str(c))
log(features("qa", off=["payslip_acknowledgement"])); c, j = t1.post(f"/payroll/payslips/{pa}/acknowledge/"); chk("switch off 403/404", c in (403, 404), str(c)); log(features("qa", on=["payslip_acknowledgement"]))
log("DB", q(f"select id,acknowledged_at,net_minor from payroll_payslip where id in ({st['slip_T1_sep']},{pa})"))
c, raw = a.get("/payroll/payslips/?format=csv", raw=True); chk("acknowledged_at in CSV header", c == 200 and "acknowledged_at" in raw.splitlines()[0], raw.splitlines()[0][:300] if raw else str(c))
st_save(st); save("tc021.txt")
